USE ticketing_system;
SET @sql = (SELECT IF(COUNT(*)=0,'ALTER TABLE roles ADD COLUMN description VARCHAR(255) NULL','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='roles' AND column_name='description'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = (SELECT IF(COUNT(*)=0,'ALTER TABLE roles ADD COLUMN backup_leader_user_id BIGINT UNSIGNED NULL','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='roles' AND column_name='backup_leader_user_id'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = (SELECT IF(COUNT(*)=0,'ALTER TABLE roles ADD COLUMN is_active TINYINT(1) NOT NULL DEFAULT 1','SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='roles' AND column_name='is_active'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = (SELECT IF(COUNT(*)=0,"ALTER TABLE role_members ADD COLUMN relation_type ENUM('MEMBER','LEADER','BACKUP_LEADER') NOT NULL DEFAULT 'MEMBER'","SELECT 1") FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='role_members' AND column_name='relation_type'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,description VARCHAR(255) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_role_permissions (system_role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(system_role_id, permission_id),FOREIGN KEY(system_role_id) REFERENCES system_roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO permissions(code,name,description) VALUES ('ticket.create','创建工单','提交新的工单'),('ticket.view_own','查看本人工单','查看自己提交或参与的工单'),('ticket.approve','审批工单','处理审批节点'),('ticket.assign','指派工单','选择执行人员'),('ticket.execute','执行工单','处理被分配的工单'),('ticket.verify','验证工单','验证处理结果'),('admin.members','管理成员','新增、编辑、停用成员'),('admin.roles','管理角色','管理业务角色与成员关系'),('admin.workflow','管理流程','配置工单流程'),('report.view','查看报表','查看统计报表') ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description);
UPDATE system_roles SET name='审批人',description='处理分配给自己的审批节点' WHERE code='leader';
